AssistantMessageToolRequest(name='create', tool_call_id='tooluse_D1kD4afgvte7YJuJFoOZim', arguments={'file_text': ':root {
    --primary-bg: #0f0f0f;
    --secondary-bg: #1a1a1a;
    --tertiary-bg: #2a2a2a;
    --text-primary: #e8e8e8;
    --text-secondary: #a8a8a8;
    --accent: #6366f1;
    --accent-hover: #818cf8;
    --border: #333333;
    --focus-ring: #60a5fa;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
    background-color: var(--primary-bg);
    color: var(--text-primary);
    line-height: 1.6;
    font-size: 16px;
}

main {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

header {
    margin-bottom: 3rem;
    text-align: center;
    border-bottom: 2px solid var(--border);
    padding-bottom: 2rem;
}

header h1 {
    font-size: 2.5rem;
    font-weight: 700;
    margin-bottom: 0.5rem;
    background: linear-gradient(135deg, var(--accent), var(--accent-hover));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

header p {
    color: var(--text-secondary);
    font-size: 1.1rem;
}

.faq-container {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.example {
    background-color: var(--secondary-bg);
    border: 1px solid var(--border);
    border-radius: 8px;
    overflow: hidden;
    transition: background-color 0.2s ease, border-color 0.2s ease;
}

.example:hover {
    background-color: var(--tertiary-bg);
    border-color: var(--accent);
}

.example h3 {
    margin: 0;
}

.example button {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: 1.25rem 1.5rem;
    background-color: transparent;
    border: none;
    color: var(--text-primary);
    cursor: pointer;
    font-size: 1.1rem;
    font-weight: 600;
    text-align: left;
    transition: all 0.2s ease;
    position: relative;
}

.example button:hover {
    color: var(--accent);
}

.example button:focus {
    outline: none;
}

.example button:focus-visible {
    box-shadow: inset 0 0 0 3px var(--focus-ring);
    background-color: rgba(96, 165, 250, 0.05);
}

/* Chevron icon */
.example button::after {
    content: '';
    display: inline-block;
    width: 20px;
    height: 20px;
    margin-left: 1rem;
    background: linear-gradient(135deg, var(--accent), var(--accent-hover));
    mask-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg>');
    mask-size: contain;
    mask-repeat: no-repeat;
    mask-position: center;
    transition: transform 0.3s ease;
    flex-shrink: 0;
}

.example button[aria-expanded="true"]::after {
    transform: rotate(180deg);
}

.details {
    padding: 0 1.5rem 1.25rem 1.5rem;
    color: var(--text-secondary);
    line-height: 1.8;
    background-color: rgba(0, 0, 0, 0.2);
    border-top: 1px solid var(--border);
}

.details p {
    margin-bottom: 0.75rem;
}

.details p:last-child {
    margin-bottom: 0;
}

/* Animation for opening/closing */
.details[hidden] {
    display: none;
}

/* Responsive design */
@media (max-width: 600px) {
    main {
        padding: 1.5rem 1rem;
    }

    header h1 {
        font-size: 1.75rem;
    }

    header p {
        font-size: 1rem;
    }

    .example button {
        padding: 1rem 1.25rem;
        font-size: 1rem;
    }

    .details {
        padding: 0 1.25rem 1rem 1.25rem;
    }
}

/* High contrast / Forced Colors support */
@media (prefers-contrast: more) {
    .example {
        border-width: 2px;
    }

    .example button:focus-visible {
        box-shadow: inset 0 0 0 4px var(--focus-ring);
    }
}

@media (forced-colors: active) {
    .example {
        border-color: CanvasText;
    }

    .example button {
        color: ButtonText;
    }

    .example button::after {
        background: ButtonText;
    }

    .details {
        background-color: Canvas;
        border-color: CanvasText;
    }

    .example button:focus-visible {
        outline: 3px solid Highlight;
        outline-offset: 2px;
    }
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }

    .example button::after {
        transition: none;
    }
}
