    // Initialize all disclosure buttons
    const buttons = document.querySelectorAll('.example button[type="button"]');

    buttons.forEach((btn) => {
        // Get the details panel (next sibling with class "details")
        const panel = btn.closest('h2').nextElementSibling;

        if (!panel || !panel.classList.contains('details')) {
            console.warn('Details panel not found for button:', btn);
            return;
        }

        // Initialize: collapse all panels on page load
        btn.setAttribute('aria-expanded', 'false');
        panel.hidden = true;

        // Handle click to toggle
        btn.addEventListener('click', () => {
            const isExpanded = btn.getAttribute('aria-expanded') === 'true';
            btn.setAttribute('aria-expanded', String(!isExpanded));
            panel.hidden = isExpanded;
        });

        // Handle keyboard: Escape to collapse
        btn.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && btn.getAttribute('aria-expanded') === 'true') {
                e.preventDefault();
                btn.setAttribute('aria-expanded', 'false');
                panel.hidden = true;
                btn.focus();
            }
        });
    });
});
